= { color: C.lightBg };\n\nslide7.addText(\"2024: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew\", {\n  x: 0.6, y: 0.3, w: 9, h: 0.7,\n  fontSize: 20, fontFace: \"Georgia\", color: C.textDark, bold: true, margin: 0\n});\n\n// Diverging bar chart for 2024 changes\nslide7.addChart(pres.charts.BAR, [{\n  name: \"Annual Change in CO₂ (%)\",\n  labels: [\"US\", \"EU-27\", \"UK\", \"Russia\", \"India\", \"SE Asia\", \"Central Asia\"],\n  values: [-3, -4, -3.5, 2, 4, 5, 10]\n}], {\n  x: 0.5, y: 1.1, w: 9, h: 3.5,\n  barDir: \"bar\",\n  chartColors: [C.accent2],\n  chartArea: { fill: { color: C.lightBg } },\n  catAxisLabelColor: C.textDark,\n  valAxisLabelColor: C.textMuted,\n  valGridLine: { color: \"E2E8F0\", size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showValue: true,\n  dataLabelPosition: \"outEnd\",\n  dataLabelColor: C.textDark,\n  showLegend: false,\n  showTitle: false,\n  valAxisTitle: \"% change (2024)\"\n});\n\n// Legend callout\nslide7.addShape(pres.shapes.RECTANGLE, {\n  x: 0.6, y: 4.8, w: 0.25, h: 0.25, fill: { color: C.us }\n});\nslide7.addText(\"Decline\", {\n  x: 0.95, y: 4.8, w: 1.2, h: 0.25,\n  fontSize: 10, fontFace: \"Calibri\", color: C.textDark, valign: \"middle\", margin: 0\n});\nslide7.addShape(pres.shapes.RECTANGLE, {\n  x: 2.3, y: 4.8, w: 0.25, h: 0.25, fill: { color: C.orange }\n});\nslide7.addText(\"Increase\", {\n  x: 2.65, y: 4.8, w: 1.2, h: 0.25,\n  fontSize: 10, fontFace: \"Calibri\", color: C.textDark, valign: \"middle\", margin: 0\n});\n\nslide7.addText(\"Some Central Asian nations (e.g. Turkmenistan/Uzbekistan) saw increases exceeding 10%.\", {\n  x: 0.6, y: 5.2, w: 8, h: 0.3,\n  fontSize: 10, fontFace: \"Calibri\", color: C.textMuted, italic: true, margin: 0\n});\n\n// === SLIDE 8: ENERGY MIX ===\nlet slide8 = pres.addSlide();\nslide8.background = { color: C.lightBg };\n\nslide8.addText(\"Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US\", {\n  x: 0.6, y: 0.3, w: 9, h: 0.7,\n  fontSize: 19, fontFace: \"Georgia\", color: C.textDark, bold: true, margin: 0\n});\n\n// Comparative bar chart\nslide8.addChart(pres.charts.BAR, [{\n  name: \"Per Capita CO₂ (t/person)\",\n  labels: [\"United States\", \"Germany\", \"Netherlands\", \"EU-27 avg.\", \"UK\", \"France\", \"Portugal\"],\n  values: [14, 8, 9, 6, 4, 4.5, 3.5]\n}], {\n  x: 0.5, y: 1.1, w: 5.5, h: 3.5,\n  barDir: \"bar\",\n  chartColors: [C.accent2],\n  chartArea: { fill: { color: C.lightBg } },\n  catAxisLabelColor: C.textDark,\n  valAxisLabelColor: C.textMuted,\n  valGridLine: { color: \"E2E8F0\", size: 0.5 },\n  catGridLine: { style: \"none\" },\n  showValue: true,\n  dataLabelPosition: \"outEnd\",\n  dataLabelColor: C.textDark,\n  showLegend: false,\n  showTitle: false\n});\n\n// Qualitative explanation box\nslide8.addShape(pres.shapes.RECTANGLE, {\n  x: 6.3, y: 1.3, w: 3.3, h: 3.2,\n  fill: { color: C.darkBg }\n});\nslide8.addText([\n  { text: \"Key driver:\", options: { bold: true, color: C.accent3, breakLine: true } },\n  { text: \"Electricity source mix\", options: { breakLine: true, color: C.white } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"France, UK, Portugal:\", options: { bold: true, breakLine: true, color: C.green } },\n  { text: \"High nuclear + renewables\", options: { breakLine: true, color: C.white } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"Germany, Netherlands, US:\", options: { bold: true, breakLine: true, color: C.orange } },\n  { text: \"Higher fossil fuel reliance\", options: { color: C.white } }\n], {\n  x: 6.5, y: 1.5, w: 3.0, h: 2.8,\n  fontSize: 12, fontFace: \"Calibri\", valign: \"top\", margin: 0\n});\n\nslide8.addText(\"Similar prosperity levels — very different emissions outcomes.\", {\n  x: 0.6, y: 5.2, w: 6, h: 0.3,\n  fontSize: 10, fontFace: \"Calibri\", color: C.textMuted, italic: true, margin: 0\n});\n\n// === SLIDE 9: KEY TAKEAWAYS ===\nlet slide9 = pres.addSlide();\nslide9.background = { color: C.darkBg };\n\n// Accent line\nslide9.addShape(pres.shapes.RECTANGLE, {\n  x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent }\n});\n\nslide9.addText(\"Key Takeaways: Responsibility Is Shared but Unequal\", {\n  x: 0.8, y: 0.4, w: 9, h: 0.7,\n  fontSize: 24, fontFace: \"Georgia\", color: C.white, bold: true, margin: 0\n});\n\nslide9.addText([\n  { text: \"Global emissions exceed 35 Bt/yr and have not yet peaked, despite slowing growth.\", options: { bullet: true, breakLine: true, color: C.white } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"China is the largest annual emitter (~31%) but per capita remains below the US (~9 t vs. ~14 t).\", options: { bullet: true, breakLine: true, color: C.white } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"Historical responsibility is dominated by Europe and the US (>90% in 1900, <33% today).\", options: { bullet: true, breakLine: true, color: C.white } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"A 150× per capita gap persists between the poorest nations (~0.1 t) and the richest (~14 t).\", options: { bullet: true, breakLine: true, color: C.white } },\n  { text: \"\", options: { breakLine: true } },\n  { text: \"Energy policy and technology choices can decouple prosperity from emissions — France and the UK demonstrate this.\", options: { bullet: true, color: C.white } }\n], {\n  x: 0.8, y: 1.4, w: 8.5, h: 3.8,\n  fontSize: 14, fontFace: \"Calibri\", valign: \"top\", margin: 0,\n  paraSpaceAfter: 2\n});\n\nslide9.addText(\"Data: Global Carbon Budget 2025 via Our World in Data  |  ourworldindata.org/co2-emissions\", {\n  x: 0.8, y: 5.0, w: 8, h: 0.4,\n  fontSize: 10, fontFace: \"Calibri\", color: C.textMuted, italic: true, margin: 0\n});\n\n// Save\npres.writeFile({ fileName: \"/app/output/final_deck.pptx\" })\n  .then(() => console.log(\"Presentation saved successfully.\"))\n  .catch(err => console.error(\"Error:\", err));\n", "numLines": 412, "startLine": 1, "totalLi