const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "Climate Analytics Team";
pres.title = "Global CO₂ Emissions: Who Emits, How Much, and What's Changing";

// Color palette - deep ocean/teal for climate data
const C = {
  darkBg: "1B2838",
  medBg: "243447",
  lightBg: "F4F7FA",
  accent: "00A8CC",
  accent2: "0D7377",
  accent3: "14BDEB",
  white: "FFFFFF",
  textDark: "1E293B",
  textMuted: "64748B",
  orange: "E8734A",
  red: "D94F4F",
  green: "2ECC71",
  gold: "F5A623",
  china: "E63946",
  us: "457B9D",
  india: "F4A261",
  eu: "2A9D8F",
  russia: "8D99AE",
  africa: "E9C46A",
};

// === SLIDE 1: TITLE ===
let slide1 = pres.addSlide();
slide1.background = { color: C.darkBg };

// Subtle geometric accent
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.1, w: 10, h: 0.08, fill: { color: C.accent, transparency: 60 }
});

slide1.addText("Global CO₂ Emissions", {
  x: 0.8, y: 1.2, w: 8.5, h: 1.2,
  fontSize: 40, fontFace: "Georgia", color: C.white, bold: true, margin: 0
});
slide1.addText("Who Emits, How Much, and What's Changing", {
  x: 0.8, y: 2.3, w: 8.5, h: 0.7,
  fontSize: 22, fontFace: "Calibri", color: C.accent3, margin: 0
});
slide1.addText("Fossil fuels & industry  |  1750–2024", {
  x: 0.8, y: 3.4, w: 8.5, h: 0.5,
  fontSize: 14, fontFace: "Calibri", color: C.textMuted, margin: 0
});
slide1.addText("Data: Global Carbon Budget 2025 via Our World in Data", {
  x: 0.8, y: 4.8, w: 6, h: 0.4,
  fontSize: 11, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});
slide1.addText("For policy analysts, climate negotiators & sustainability researchers", {
  x: 0.8, y: 3.9, w: 8, h: 0.4,
  fontSize: 12, fontFace: "Calibri", color: C.textMuted, margin: 0
});

// === SLIDE 2: GLOBAL EMISSIONS GROWTH (Area chart) ===
let slide2 = pres.addSlide();
slide2.background = { color: C.lightBg };

slide2.addText("Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 22, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Area chart with approximate data points
const emissionsLabels = ["1750", "1800", "1850", "1900", "1920", "1940", "1950", "1960", "1970", "1980", "1990", "2000", "2010", "2020", "2024"];
const emissionsValues = [0.01, 0.03, 0.2, 2, 3.5, 5, 6, 9, 14, 18, 22, 25, 31, 34, 35.5];

slide2.addChart(pres.charts.AREA, [{
  name: "Global CO₂ (Bt/yr)",
  labels: emissionsLabels,
  values: emissionsValues
}], {
  x: 0.5, y: 1.1, w: 9, h: 3.8,
  chartColors: [C.accent2],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textMuted,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showLegend: false,
  showTitle: false,
  valAxisTitle: "Billion tonnes CO₂/yr",
  valAxisTitleColor: C.textMuted,
  opacity: 80
});

// Annotation callouts
slide2.addText("Post-1950\nacceleration", {
  x: 4.5, y: 3.4, w: 1.6, h: 0.7,
  fontSize: 9, fontFace: "Calibri", color: C.accent2, italic: true, align: "center", margin: 0
});
slide2.addText("No peak yet", {
  x: 8.0, y: 1.6, w: 1.3, h: 0.4,
  fontSize: 9, fontFace: "Calibri", color: C.orange, bold: true, align: "center", margin: 0
});

slide2.addText("Source: Global Carbon Budget 2025", {
  x: 0.6, y: 5.2, w: 4, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});

// === SLIDE 3: REGIONAL SHARE SHIFT ===
let slide3 = pres.addSlide();
slide3.background = { color: C.lightBg };

slide3.addText("Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 20, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Stacked area chart showing regional shares
const shareLabels = ["1900", "1950", "1970", "1990", "2000", "2010", "2024"];
slide3.addChart(pres.charts.AREA, [
  { name: "Europe & US", labels: shareLabels, values: [90, 85, 65, 50, 40, 33, 30] },
  { name: "China", labels: shareLabels, values: [0, 2, 6, 11, 14, 25, 31] },
  { name: "India", labels: shareLabels, values: [0, 1, 2, 3, 4, 6, 8] },
  { name: "Rest of World", labels: shareLabels, values: [10, 12, 27, 36, 42, 36, 31] }
], {
  x: 0.5, y: 1.1, w: 9, h: 3.6,
  chartColors: [C.us, C.china, C.india, C.textMuted],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textMuted,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showLegend: true,
  legendPos: "b",
  showTitle: false,
  barGrouping: "stacked"
});

slide3.addText("Share of global CO₂ emissions (%)", {
  x: 0.6, y: 4.9, w: 4, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});

// === SLIDE 4: CHINA DOMINATES ===
let slide4 = pres.addSlide();
slide4.background = { color: C.lightBg };

slide4.addText("China Now Emits More Than One-Quarter of Global CO₂", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 22, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Bar chart for country shares
slide4.addChart(pres.charts.BAR, [{
  name: "Share of Global CO₂ (2024)",
  labels: ["China", "United States", "India", "EU-27", "Russia", "Africa", "S. America", "Int'l transport"],
  values: [31, 13, 8, 6, 5, 3.5, 3.5, 3]
}], {
  x: 0.5, y: 1.1, w: 9, h: 4.0,
  barDir: "bar",
  chartColors: [C.china],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  showLegend: false,
  showTitle: false,
  valAxisTitle: "% of global CO₂"
});

slide4.addText("Africa and South America each account for only 3–4% — comparable to international aviation & shipping.", {
  x: 0.6, y: 5.2, w: 8, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});

// === SLIDE 5: PER CAPITA INEQUALITY (Horizontal bar chart) ===
let slide5 = pres.addSlide();
slide5.background = { color: C.lightBg };

slide5.addText("Per Capita Emissions Range from 0.1 t in Chad to ~14 t in the US and Canada", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 20, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Horizontal bar chart
slide5.addChart(pres.charts.BAR, [{
  name: "Per Capita CO₂ (t/person, 2024)",
  labels: ["United States", "Canada", "China", "South Africa", "EU-27", "World avg.", "UK", "India", "Kenya", "Chad"],
  values: [14, 14, 9, 7, 6, 4.5, 4, 2, 0.4, 0.1]
}], {
  x: 0.5, y: 1.0, w: 9, h: 4.1,
  barDir: "bar",
  chartColors: [C.accent],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  showLegend: false,
  showTitle: false,
  valAxisTitle: "tonnes CO₂/person"
});

// Callout for 150x gap
slide5.addShape(pres.shapes.RECTANGLE, {
  x: 6.8, y: 1.0, w: 2.8, h: 0.9,
  fill: { color: C.darkBg }, rectRadius: 0.05
});
slide5.addText("150×\ngap", {
  x: 6.8, y: 1.0, w: 2.8, h: 0.9,
  fontSize: 22, fontFace: "Georgia", color: C.accent3, bold: true,
  align: "center", valign: "middle", margin: 0
});

slide5.addText("Source: Global Carbon Budget 2025 via Our World in Data", {
  x: 0.6, y: 5.2, w: 5, h: 0.3,
  fontSize: 9, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});

// === SLIDE 6: PER CAPITA TRENDS OVER TIME ===
let slide6 = pres.addSlide();
slide6.background = { color: C.lightBg };

slide6.addText("Per Capita Emissions: ~14 t in the US vs. ~9 t in China and ~2 t in India", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 20, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Multi-line chart showing per capita trends
const pcLabels = ["1990", "2000", "2005", "2010", "2015", "2020", "2024"];
slide6.addChart(pres.charts.LINE, [
  { name: "US (~14 t)", labels: pcLabels, values: [19, 20, 19.5, 17, 16, 14.5, 14] },
  { name: "China (~9 t)", labels: pcLabels, values: [2.1, 2.7, 4.5, 6.5, 7.5, 8, 9] },
  { name: "EU-27 (~6 t)", labels: pcLabels, values: [8.5, 8, 8, 7, 6.5, 5.5, 6] },
  { name: "India (~2 t)", labels: pcLabels, values: [0.7, 1, 1.2, 1.5, 1.7, 1.8, 2] },
  { name: "World avg. (~4.5 t)", labels: pcLabels, values: [3.8, 3.9, 4.2, 4.5, 4.6, 4.3, 4.5] }
], {
  x: 0.5, y: 1.1, w: 9, h: 3.6,
  chartColors: [C.us, C.china, C.eu, C.india, C.textMuted],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textMuted,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showLegend: true,
  legendPos: "r",
  showTitle: false,
  lineSize: 2.5,
  lineSmooth: true,
  valAxisTitle: "t CO₂ / person"
});

slide6.addText("China's per capita emissions remain below the US despite being the largest total emitter.", {
  x: 0.6, y: 5.0, w: 8, h: 0.4,
  fontSize: 10, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});

// === SLIDE 7: 2024 ANNUAL CHANGE ===
let slide7 = pres.addSlide();
slide7.background = { color: C.lightBg };

slide7.addText("2024: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 20, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Diverging bar chart for 2024 changes
slide7.addChart(pres.charts.BAR, [{
  name: "Annual Change in CO₂ (%)",
  labels: ["US", "EU-27", "UK", "Russia", "India", "SE Asia", "Central Asia"],
  values: [-3, -4, -3.5, 2, 4, 5, 10]
}], {
  x: 0.5, y: 1.1, w: 9, h: 3.5,
  barDir: "bar",
  chartColors: [C.accent2],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  showLegend: false,
  showTitle: false,
  valAxisTitle: "% change (2024)"
});

// Legend callout
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 0.6, y: 4.8, w: 0.25, h: 0.25, fill: { color: C.us }
});
slide7.addText("Decline", {
  x: 0.95, y: 4.8, w: 1.2, h: 0.25,
  fontSize: 10, fontFace: "Calibri", color: C.textDark, valign: "middle", margin: 0
});
slide7.addShape(pres.shapes.RECTANGLE, {
  x: 2.3, y: 4.8, w: 0.25, h: 0.25, fill: { color: C.orange }
});
slide7.addText("Increase", {
  x: 2.65, y: 4.8, w: 1.2, h: 0.25,
  fontSize: 10, fontFace: "Calibri", color: C.textDark, valign: "middle", margin: 0
});

slide7.addText("Some Central Asian nations (e.g. Turkmenistan/Uzbekistan) saw increases exceeding 10%.", {
  x: 0.6, y: 5.2, w: 8, h: 0.3,
  fontSize: 10, fontFace: "Calibri", color: C.textMuted, italic: true, margin: 0
});

// === SLIDE 8: ENERGY MIX ===
let slide8 = pres.addSlide();
slide8.background = { color: C.lightBg };

slide8.addText("Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US", {
  x: 0.6, y: 0.3, w: 9, h: 0.7,
  fontSize: 19, fontFace: "Georgia", color: C.textDark, bold: true, margin: 0
});

// Comparative bar chart
slide8.addChart(pres.charts.BAR, [{
  name: "Per Capita CO₂ (t/person)",
  labels: ["United States", "Germany", "Netherlands", "EU-27 avg.", "UK", "France", "Portugal"],
  values: [14, 8, 9, 6, 4, 4.5, 3.5]
}], {
  x: 0.5, y: 1.1, w: 5.5, h: 3.5,
  barDir: "bar",
  chartColors: [C.accent2],
  chartArea: { fill: { color: C.lightBg } },
  catAxisLabelColor: C.textDark,
  valAxisLabelColor: C.textMuted,
  valGridLine: { color: "E2E8F0", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: C.textDark,
  showLegend: false,
  showTitle: false
});

// Qualitative explanation box
slide8.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.3, w: 3.3, h: 3.2,
  fill: { color: C.darkBg }
});
slide8.addText([
  { text: "Key driver:", options: { bold: true, color: C.accent3, breakLine: true } },
  { text: "Electricity source mix", options: { breakLine: true, color: C.white } },
  { text: "", options: { breakLine: true } },
  { text: "France, UK, Portugal:", options: { bold: true, breakLine: true, color: C.green } },
  { text: "High nuclear + renewables", options: { breakLine: true, color: C.white } },
  { text: "", options: { breakLine: true } },
  { text: "Germany, Netherlands, US:", options: { bold: true, breakLine: true, color: C.orange } },
  { text: "Higher fossil fuel reliance", options: { color: C.white } }
], {
  x: 6.5, y: 1.5, w: 3.0, h: 2.8,
  fontSize: 12, fontFace: "Calibri", valign: "top", margin: 0
});

